// HMAC-SHA256 over `${timestamp}.${METHOD}.${path}.${body}` (see convex/lib/hmac.ts).
// The secret comes from the n8n host environment, never from this workflow JSON.
const crypto = require('crypto');
const secret = $env.N8N_TO_LENDLOOP_SECRET;
if (!secret) throw new Error('N8N_TO_LENDLOOP_SECRET is not set on the n8n host');
function sign(method, path, body) {
  const timestamp = String(Math.floor(Date.now() / 1000));
  const hex = crypto.createHmac('sha256', secret)
    .update(`${timestamp}.${method}.${path}.${body}`)
    .digest('hex');
  return { timestamp, signature: `sha256=${hex}` };
}

return [{ json: sign('GET', '/n8n/overdue-loans', '') }];

// One item per overdue loan. Convex already skips loans reminded today.
const { asOf, loans } = $input.first().json;
console.log(`[lendloop] overdue check ${asOf}: ${loans.length} loan(s)`);
return loans.map((loan) => ({ json: { ...loan, asOf } }));

// Mock reminder (swap for Email/Slack in production). Runs once per loan.
return $input.all().map(({ json: loan }) => {
  const reminder = {
    channel: loan.borrower?.email ? 'mock-email' : 'log-only (no email on file)',
    to: loan.borrower?.email ?? null,
    subject: `Reminder: please return the ${loan.toolName}`,
    text: `Hi ${loan.borrower?.name ?? 'there'}, the ${loan.toolName} was due back on ${loan.endDate} ` +
      `(${loan.daysOverdue} day${loan.daysOverdue === 1 ? '' : 's'} ago). Please return it or contact the owner in LendLoop.`,
  };
  console.log('[lendloop] MOCK REMINDER', JSON.stringify(reminder));
  return { json: { requestId: loan.requestId, dedupeKey: loan.dedupeKey, reminder } };
});

// HMAC-SHA256 over `${timestamp}.${METHOD}.${path}.${body}` (see convex/lib/hmac.ts).
// The secret comes from the n8n host environment, never from this workflow JSON.
const crypto = require('crypto');
const secret = $env.N8N_TO_LENDLOOP_SECRET;
if (!secret) throw new Error('N8N_TO_LENDLOOP_SECRET is not set on the n8n host');
function sign(method, path, body) {
  const timestamp = String(Math.floor(Date.now() / 1000));
  const hex = crypto.createHmac('sha256', secret)
    .update(`${timestamp}.${method}.${path}.${body}`)
    .digest('hex');
  return { timestamp, signature: `sha256=${hex}` };
}

// The dedupeKey (reminder:<requestId>:<YYYY-MM-DD>) makes the write-back idempotent.
return $input.all().map(({ json }) => {
  const body = JSON.stringify({ requestId: json.requestId, type: 'overdue_reminder', dedupeKey: json.dedupeKey });
  return { json: { body, ...sign('POST', '/n8n/events', body) } };
});

const results = $input.all().map((i) => i.json);
const summary = {
  recorded: results.filter((r) => r.ok && !r.duplicate).length,
  duplicates: results.filter((r) => r.ok && r.duplicate).length,
};
console.log('[lendloop] overdue reminders written back', JSON.stringify(summary));
return [{ json: summary }];
